COPY={}
def page(n,en,es,se,ss,ce,cs,fe,fs):
 COPY[f'DD-{n:03d}']={'en':dict(title=en[0],intro=en[1],sections=se,checklist=ce,faq=fe),'es':dict(title=es[0],intro=es[1],sections=ss,checklist=cs,faq=fs)}
page(23,('Doberman history and the role of breed standards','Follow a few documented milestones, then distinguish breed history from today’s registration standards. Historical working roles provide context; they do not determine an individual dog’s behavior or care needs.'),('Historia del dóberman y función de los estándares','Sigue hitos documentados y distingue historia de estándares actuales. Las funciones históricas dan contexto, sin determinar conducta ni necesidades individuales.'),[
('Begin with the documented origin','The FCI history describes Friedrich Louis Dobermann’s breeding work in Germany during the 1870s. Historical accounts discuss working and protective roles, but the exact ancestry should not be reduced to a confidently asserted recipe when the evidence is uncertain. Use attributed sources rather than repeating an unsourced list of foundation breeds.'),('Separate recognition from later development','The AKC breed page records recognition in 1908 and the founding of the Doberman Pinscher Club of America in 1921. These dates describe institutional milestones, not an instant final version of the breed. The timeline below keeps each event attached to its source organization.'),('Read a standard as an evaluation document','AKC and FCI standards describe the ideal evaluated dog within their systems. They address appearance, movement and other criteria, but they are not puppy growth charts or individual health assessments. Keep the organization, document date and relevant jurisdiction visible when discussing a requirement.'),('Understand historical context without copying it into care','A historical image or account can show practices from another time without recommending them today. This page uses a contemporary credited portrait, not an archival photograph. Decisions about a dog’s care need current professional advice and applicable local requirements rather than historical appearance alone.'),('A worked source check','Example: a claim says the breed was recognized in a certain year. Record the claimed event, identify whether it refers to AKC recognition or another organization, then verify that organization’s account. Different milestones can coexist; a date without its event label is easy to misinterpret.')],[
('Empieza por el origen documentado','La historia FCI describe crianza de Friedrich Louis Dobermann en Alemania durante los años 1870. Las funciones de trabajo y protección dan contexto, pero no conviertas ascendencia incierta en una receta de razas presentada como segura. Atribuye fuentes.'),('Separa reconocimiento y desarrollo','AKC registra reconocimiento en 1908 y fundación del club estadounidense en 1921. Son hitos institucionales, no una versión final inmediata de la raza. La cronología conserva evento y organización.'),('Lee el estándar como evaluación','AKC y FCI describen el perro ideal en sus sistemas, incluyendo aspecto y movimiento. No son tablas de crecimiento ni valoración de salud. Conserva organización, fecha y jurisdicción al explicar requisitos.'),('Comprende contexto sin convertirlo en cuidados','Una imagen histórica muestra prácticas de otra época sin recomendarlas hoy. Aquí usamos retrato contemporáneo acreditado, no fotografía de archivo. Los cuidados necesitan orientación actual y requisitos locales.'),('Ejemplo de verificación','Una afirmación propone año de reconocimiento. Anota evento, distingue reconocimiento AKC de otra entidad y consulta su relato. Pueden coexistir hitos distintos; fecha sin evento se interpreta mal.')],['Record the event and organization behind each date.','Use official sources for registration milestones.','Distinguish standards from growth or health advice.','Label historical context and contemporary illustrations clearly.'],['Anota evento y organización de cada fecha.','Consulta fuentes oficiales para reconocimiento.','Separa estándares de crecimiento y salud.','Distingue contexto histórico e imágenes actuales.'],[('Does a working history predict my dog’s temperament?','No. Learn about the individual dog’s history, behavior and needs.'),('Are AKC and FCI standards identical?','They are separate documents. Check the named standard rather than treating requirements as universal.')],[('¿La historia de trabajo predice temperamento?','No. Conoce historia, conducta y necesidades del individuo.'),('¿AKC y FCI son idénticos?','Son documentos distintos. Consulta el estándar concreto.')])
page(31,('Puppy development: track your Doberman’s changing needs','Physical growth, confidence and learned skills do not advance on one shared timetable. Observe your puppy, keep experiences manageable and use your veterinary team’s individual guidance.'),('Desarrollo del cachorro: observa necesidades cambiantes','Crecimiento físico, confianza y habilidades no siguen un mismo calendario. Observa, ofrece experiencias manejables y sigue orientación veterinaria individual.'),[
('Separate three kinds of progress','Growth measurements describe the body; comfort describes responses to experiences; training records describe a learned behavior in a particular setting. A puppy who is taller may still need easier handling practice. Do not use physical size to justify expecting adult reliability or endurance.'),('Plan early experiences with professional guidance','Discuss suitable socialization opportunities and infection-risk precautions with your veterinary team. AVSAB emphasizes positive experiences rather than mere exposure. Let your puppy move away and keep situations easy; crowded or frightening encounters do not become useful simply because they happen early.'),('Build everyday skills in small steps','Introduce toileting routines, rest, comfortable handling and simple reward-based practice. Measure success by what your puppy can do comfortably today, not a deadline from another dog’s training diary. Repeat easier steps when distractions increase and allow breaks.'),('Adapt through adolescence','As surroundings become more interesting, familiar responses may be harder in busy places. Revisit easy settings and managed access rather than interpreting every missed cue as stubbornness. Physical development and behavioral changes vary, so adjust your expectations to observations rather than imposing a universal age cutoff.'),('A worked progress record','Example: body—record a measurement with its method; comfort—approaches a brush voluntarily; skill—responds to a cue in the kitchen but not outdoors; next step—practice with one easy outdoor distraction. This is a record format, not a growth target, developmental diagnosis or guarantee.')],[
('Distingue tres avances','Medidas describen cuerpo; comodidad, respuesta a experiencias; registro de práctica, conducta aprendida en un entorno. Ser más alto no implica tolerar más manejo. No esperes fiabilidad o resistencia adulta por tamaño.'),('Planifica experiencias tempranas','Consulta socialización apropiada y precauciones infecciosas al equipo veterinario. AVSAB destaca experiencias positivas, no exposición por sí sola. Permite retirarse y facilita situaciones; encuentros aterradores no ayudan solo por ser tempranos.'),('Construye habilidades pequeñas','Introduce baño, descanso, manejo cómodo y práctica con premios. Valora lo que logra hoy con comodidad, no plazos de otro perro. Repite pasos fáciles ante distracciones y permite pausas.'),('Adapta en adolescencia','Entornos interesantes dificultan respuestas conocidas. Vuelve a lugares fáciles y acceso controlado sin asumir terquedad. Desarrollo físico y conducta varían: adapta expectativas a observaciones, no una edad universal.'),('Ejemplo de registro','Cuerpo: medida y método. Comodidad: se acerca voluntariamente al cepillo. Habilidad: responde en cocina pero no fuera. Próximo paso: una distracción exterior fácil. Es formato de observación, no meta, diagnóstico ni garantía.')],['Track body, comfort and skills separately.','Discuss safe socialization with your veterinary team.','Practice small steps with reward and breaks.','Adjust difficulty to the individual puppy.'],['Separa cuerpo, comodidad y habilidades.','Consulta socialización segura al veterinario.','Practica pasos pequeños con premios y pausas.','Adapta dificultad al cachorro.'],[('Should all puppies reach skills at the same age?','No. Record the setting and individual response, then adapt practice.'),('Does being bigger mean my puppy is ready for adult exercise?','No. Discuss appropriate activity with your veterinarian rather than using size alone.')],[('¿Todos aprenden a la misma edad?','No. Registra entorno y respuesta y adapta práctica.'),('¿Ser más grande implica ejercicio adulto?','No. Consulta actividad apropiada sin guiarte solo por talla.')])
page(32,('Help your Doberman puppy rest and settle at night','Provide a comfortable quiet place, meet ordinary needs and observe waking calmly. A useful sleep record explains what happened; it does not impose a guaranteed number of hours or diagnose the cause of disturbed sleep.'),('Ayuda a tu cachorro a descansar por la noche','Ofrece lugar tranquilo cómodo, atiende necesidades y observa despertares con calma. El registro explica lo sucedido, sin imponer horas garantizadas ni diagnosticar sueño alterado.'),[
('Prepare comfortable rest before bedtime','Choose a secure quiet area with suitable bedding and comfortable conditions. Introduce it gently rather than assuming a new puppy can settle alone immediately. Keep a route for necessary toilet trips and share the plan with caregivers. If a crate is used, comfort with it must be introduced separately.'),('Make the evening predictable','Allow suitable toileting, water access and a calm transition from activity to rest. Avoid trying to exhaust your puppy through increasingly intense play. Protect daytime rest as well as nighttime sleep; household interruptions can make a comfortable resting opportunity harder to use.'),('Respond to waking by checking needs','Notice when waking occurs and whether toileting, noise, discomfort or separation may be relevant. Keep necessary nighttime care calm rather than turning every waking into a game. Do not ignore distress on the assumption that all crying is attention seeking. Ask for individual support when settling remains difficult.'),('A worked observation log','Illustrative entry: resting place—quiet bedroom area; waking—after a corridor noise; response—calm check and a needed toilet opportunity; outcome—settled again; next question—can household noise be reduced? Record approximate times from your own observations. This example does not establish a medical cause or a required sleep duration.'),('Know when routine advice is insufficient','New pain signs, breathing difficulty, marked lethargy or inability to settle with other illness signs needs veterinary advice; urgent concerns need urgent care. Share repeated disturbed sleep and changes in appetite or behavior with your veterinary team. Keep the log factual instead of selecting a diagnosis from the internet.')],[
('Prepara descanso antes','Elige lugar seguro tranquilo, cama adecuada y condiciones cómodas. Preséntalo suavemente sin asumir que puede dormir solo enseguida. Organiza salidas al baño y comparte plan. Si usas jaula, introduce comodidad por separado.'),('Haz previsible la tarde','Ofrece baño, acceso a agua y transición tranquila. Evita agotar mediante juego cada vez más intenso. Protege descanso diurno y nocturno; interrupciones domésticas dificultan aprovecharlo.'),('Comprueba necesidades al despertar','Observa momento y posible relación con baño, ruido, molestias o separación. Mantén cuidados tranquilos sin convertir cada despertar en juego. No ignores angustia asumiendo búsqueda de atención. Solicita apoyo individual ante dificultad persistente.'),('Ejemplo de registro','Lugar: dormitorio tranquilo. Despertar: ruido del pasillo. Respuesta: comprobación calmada y salida necesaria al baño. Resultado: vuelve a descansar. Pregunta: reducir ruido doméstico. Anota horas aproximadas propias. No demuestra causa médica ni duración necesaria.'),('Cuándo consultar','Dolor nuevo, dificultad respiratoria, letargo marcado o incapacidad de descansar con signos de enfermedad requieren consulta; preocupaciones urgentes, atención urgente. Comparte alteraciones repetidas y cambios de apetito o conducta. Registra hechos sin elegir diagnóstico por internet.')],['Prepare comfortable rest and a toilet-access plan.','Protect daytime rest and a calm evening transition.','Record waking, context, response and recovery.','Discuss persistent changes or illness signs with your veterinarian.'],['Prepara descanso y acceso al baño.','Protege descanso diurno y transición tranquila.','Registra despertar, contexto, respuesta y recuperación.','Consulta cambios persistentes o enfermedad.'],[('Is there one sleep-hours target for every puppy?','No. Individual needs and circumstances vary; discuss concerns with your veterinary team.'),('Should I ignore every nighttime cry?','No. Check ordinary needs and comfort and seek help for distress or illness concerns.')],[('¿Hay horas objetivo para todos?','No. Necesidades y circunstancias varían; consulta dudas al veterinario.'),('¿Ignoro todo llanto nocturno?','No. Revisa necesidades y comodidad y busca apoyo ante angustia o enfermedad.')])
for lang in ('en','es'):
 COPY['DD-023'][lang]['asset_title']='Documented history milestones' if lang=='en' else 'Hitos históricos documentados'
 COPY['DD-023'][lang]['matrix']=[('1870s · FCI history','Breeding work in Germany associated with Friedrich Louis Dobermann'),('1908 · AKC','Breed recognition'),('1921 · AKC','Doberman Pinscher Club of America founded'),('Today','Read the named current standard separately from historical accounts')] if lang=='en' else [('Años 1870 · FCI','Crianza en Alemania vinculada a Friedrich Louis Dobermann'),('1908 · AKC','Reconocimiento de la raza'),('1921 · AKC','Fundación del club estadounidense'),('Actualidad','Separa estándares vigentes y relatos históricos')]
 COPY['DD-031'][lang]['asset_title']='Development checkpoints, without fixed deadlines' if lang=='en' else 'Etapas de observación sin plazos fijos'
 COPY['DD-031'][lang]['matrix']=[('Early experiences','Veterinary-guided positive socialization and rest'),('Growing skills','Small reward-based steps and comfortable handling'),('Adolescence','Revisit easy tasks when distraction increases'),('Ongoing care','Record individual changes and professional advice')] if lang=='en' else [('Experiencias tempranas','Socialización positiva orientada y descanso'),('Habilidades','Pasos pequeños y manejo cómodo'),('Adolescencia','Facilita tareas ante distracción'),('Cuidados continuos','Registra cambios e instrucciones individuales')]
 COPY['DD-032'][lang]['asset_title']='Your sleep-observation fields' if lang=='en' else 'Campos de observación del sueño'
 COPY['DD-032'][lang]['matrix']=[('Time and place','Approximate resting and waking times; quiet-area conditions'),('Context','Noise, toileting and observable comfort'),('Response','What the caregiver did without diagnosing'),('Recovery and question','Whether rest resumed and what to ask the veterinary team')] if lang=='en' else [('Hora y lugar','Horas aproximadas y condiciones del lugar'),('Contexto','Ruido, baño y comodidad observable'),('Respuesta','Actuación del cuidador sin diagnosticar'),('Recuperación y pregunta','Si descansa de nuevo y qué consultar')]
